// Shared by the extractors: a generated TypeScript module with a fixed header.

// Objects are indented; an array of objects or arrays is one compact line per item, so a
// regenerated file diffs row by row.
function format(value, indent) {
  const pad = "  ".repeat(indent);
  const inner = "  ".repeat(indent + 1);
  if (Array.isArray(value)) {
    if (value.length === 0) return "[]";
    const nested = value.some((v) => v !== null && typeof v === "object");
    if (!nested) return JSON.stringify(value);
    return `[\n${value.map((v) => `${inner}${JSON.stringify(v)}`).join(",\n")}\n${pad}]`;
  }
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value);
    if (entries.length === 0) return "{}";
    return `{\n${entries.map(([k, v]) => `${inner}${JSON.stringify(k)}: ${format(v, indent + 1)}`).join(",\n")}\n${pad}}`;
  }
  return JSON.stringify(value);
}

export function tsModule(by, sources, entries) {
  const parts = [`// Generated by ${by} from ${sources}. Do not edit; run \`pnpm gen:handoff\`.`];
  for (const [name, value] of entries) {
    parts.push(`export const ${name} = ${format(value, 0)} as const;`);
  }
  return `${parts.join("\n\n")}\n`;
}
